// El modelo devuelve el HTML del lead magnet; quitamos posibles ```html ... ```
let t = $input.first().json.text || '';
const m = t.match(/```(?:html)?\s*([\s\S]*?)```/i);
if (m) t = m[1];
if (!/<html/i.test(t)) t = `<!doctype html><html><head><meta charset="utf-8"></head><body><pre style="white-space:pre-wrap">${t.replace(/</g,'&lt;')}</pre></body></html>`;
return [{ json: { page: t } }];
